from __future__ import annotations

import json
import os

from ledgerlock import format as fmt
from ledgerlock import store


class ConflictError(Exception):
    """Raised when a mutation targets a key already committed under a different rid."""


class Ledger:
    def __init__(self, path):
        self.path = os.fspath(path)

    def append(self, operation):
        return append(self, operation)

    def verify(self):
        return verify(self)

    def snapshot(self):
        return snapshot(self)

    def apply_batch(self, operations):
        return apply_batch(self, operations)


def append(ledger, operation):
    op = operation[0]
    if op == "put":
        if len(operation) != 5:
            raise ValueError("put requires (op, key, value, rid, ts)")
        _, raw_key, value, rid, ts = operation
        fields = {"op": "put", "key": None, "value": value, "ts": ts, "id": rid}
    elif op == "delete":
        if len(operation) != 4:
            raise ValueError("delete requires (op, key, rid, ts)")
        _, raw_key, rid, ts = operation
        fields = {"op": "delete", "key": None, "ts": ts, "id": rid}
    else:
        raise ValueError(f"unknown op: {op!r}")

    key = fmt.normalize_key(raw_key)
    if key == "":
        raise ValueError("empty key")

    fields["key"] = key

    prev_hash = _tail_hash(ledger.path)
    fields["prev_hash"] = prev_hash

    line_hash = fmt.line_hash(prev_hash, fields)
    fields["hash"] = line_hash

    line_bytes = (
        json.dumps(fields, sort_keys=True, separators=(",", ":"), ensure_ascii=False).encode(
            "utf-8"
        )
        + b"\n"
    )

    _append_bytes(ledger.path, line_bytes)

    return fields


def verify(ledger):
    raise NotImplementedError


def snapshot(ledger):
    raise NotImplementedError


def apply_batch(ledger, operations):
    raise NotImplementedError


def _tail_hash(path):
    try:
        lines = store.read_lines(path)
    except FileNotFoundError:
        return fmt.GENESIS
    if not lines:
        return fmt.GENESIS
    last = json.loads(lines[-1].decode("utf-8"))
    return last["hash"]


def _append_bytes(path, data):
    with open(path, "ab") as f:
        f.write(data)
        f.flush()
        os.fsync(f.fileno())

