from __future__ import annotations

import json
import os

from ledgerlock import format as fmt
from ledgerlock import store


class ConflictError(Exception):
    """Raised when a mutation targets a key already committed under a different rid."""

    def __init__(self, key, incoming_rid, committed_rid, batch_index=None):
        self.key = key
        self.incoming_rid = incoming_rid
        self.committed_rid = committed_rid
        self.batch_index = batch_index
        super().__init__(
            "conflict on key {!r}: incoming rid {!r} != committed rid {!r}".format(
                key, incoming_rid, committed_rid
            )
        )


class Ledger:
    def __init__(self, path):
        self.path = os.fspath(path)

    def append(self, operation):
        return append(self, operation)

    def verify(self):
        return verify(self)

    def snapshot(self):
        return snapshot(self)

    def apply_batch(self, operations):
        return apply_batch(self, operations)

    def repair_tail(self):
        return repair_tail(self)


def append(ledger, operation):
    fields, key, rid = _parse_operation(operation)

    index, prev_hash = _load_state_or_empty(ledger.path)
    committed = index.get(key)
    if committed is not None:
        if committed["id"] == rid:
            result = dict(committed)
            result["replayed"] = True
            result["committed"] = False
            return result
        raise ConflictError(key=key, incoming_rid=rid, committed_rid=committed["id"])

    fields["prev_hash"] = prev_hash
    fields["hash"] = fmt.line_hash(prev_hash, fields)

    _append_bytes(ledger.path, fmt.canonical_bytes(fields) + b"\n")

    fields["replayed"] = False
    fields["committed"] = True
    return fields


def verify(ledger):
    lines = store.read_lines(ledger.path)
    prev_hash = fmt.GENESIS
    for i, raw in enumerate(lines):
        try:
            line = json.loads(raw.decode("utf-8"))
        except (json.JSONDecodeError, UnicodeDecodeError):
            return {"ok": False, "first_bad_index": i}
        if not isinstance(line, dict):
            return {"ok": False, "first_bad_index": i}
        if line.get("prev_hash") != prev_hash:
            return {"ok": False, "first_bad_index": i}
        if line.get("hash") != fmt.line_hash(prev_hash, line):
            return {"ok": False, "first_bad_index": i}
        prev_hash = line["hash"]
    return {"ok": True, "first_bad_index": None}


def snapshot(ledger):
    index, _ = _load_state(ledger.path)
    out = {}
    for key in sorted(index):
        line = index[key]
        if line.get("op") == "put":
            out[key] = line.get("value")
    return out


def apply_batch(ledger, operations):
    operations = list(operations)

    index, tail_hash = _load_state_or_empty(ledger.path)
    prev_hash = tail_hash
    new_fields = []

    for i, operation in enumerate(operations):
        fields, key, rid = _parse_operation(operation)
        committed = index.get(key)
        if committed is not None:
            if committed["id"] == rid:
                continue
            raise ConflictError(
                key=key,
                incoming_rid=rid,
                committed_rid=committed["id"],
                batch_index=i,
            )
        fields["prev_hash"] = prev_hash
        fields["hash"] = fmt.line_hash(prev_hash, fields)
        new_fields.append(fields)
        index[key] = fields
        prev_hash = fields["hash"]

    if not new_fields:
        return []

    try:
        existing = store.read_lines(ledger.path)
    except FileNotFoundError:
        existing = []

    out = [raw + b"\n" for raw in existing]
    for fields in new_fields:
        out.append(fmt.canonical_bytes(fields) + b"\n")
    store.write_atomic(ledger.path, out)

    for fields in new_fields:
        fields["replayed"] = False
        fields["committed"] = True
    return new_fields


def repair_tail(ledger):
    path = ledger.path
    with open(path, "rb") as f:
        data = f.read()

    lines = data.split(b"\n")
    if lines and lines[-1] == b"":
        lines.pop()

    verdict = verify(ledger)
    if verdict["ok"]:
        return verdict

    i = verdict["first_bad_index"]
    n = len(lines)
    if i is None or i != n - 1:
        return verdict

    last_line = lines[-1]
    truncated = (not data.endswith(b"\n")) or (not _parses(last_line))
    if not truncated:
        return verdict

    new_lines = [raw + b"\n" for raw in lines[:-1]]
    store.write_atomic(path, new_lines)
    return verify(ledger)


def _parse_operation(operation):
    if not isinstance(operation, (tuple, list)):
        raise ValueError(
            "operation must be a tuple or list, got {!r}".format(type(operation).__name__)
        )
    if not operation:
        raise ValueError("empty operation")
    op = operation[0]
    if op == "put":
        if len(operation) != 5:
            raise ValueError("put requires (op, key, value, rid, ts)")
        _, raw_key, value, rid, ts = operation
        key = _validate_key(raw_key)
        return {"op": "put", "key": key, "value": value, "ts": ts, "id": rid}, key, rid
    if op == "delete":
        if len(operation) != 4:
            raise ValueError("delete requires (op, key, rid, ts)")
        _, raw_key, rid, ts = operation
        key = _validate_key(raw_key)
        return {"op": "delete", "key": key, "ts": ts, "id": rid}, key, rid
    raise ValueError("unknown op: {!r}".format(op))


def _validate_key(raw_key):
    if not isinstance(raw_key, str):
        raise ValueError("key must be a string, got {!r}".format(type(raw_key).__name__))
    key = fmt.normalize_key(raw_key)
    if key == "":
        raise ValueError("empty key")
    return key


def _load_state(path):
    lines = store.read_lines(path)
    index = {}
    tail_hash = fmt.GENESIS
    for raw in lines:
        line = json.loads(raw.decode("utf-8"))
        index[line["key"]] = line
        tail_hash = line["hash"]
    return index, tail_hash


def _load_state_or_empty(path):
    try:
        return _load_state(path)
    except FileNotFoundError:
        return {}, fmt.GENESIS


def _parses(raw):
    try:
        json.loads(raw.decode("utf-8"))
        return True
    except (json.JSONDecodeError, UnicodeDecodeError):
        return False


def _append_bytes(path, data):
    with open(path, "ab") as f:
        f.write(data)
        f.flush()
        os.fsync(f.fileno())

